return $input.all().map(i => ({
  json: {
    title: i.json.title || 'Untitled',
    link: i.json.link || '',
    snippet: i.json.contentSnippet || '',
    pubDate: i.json.pubDate || new Date().toISOString(),
    source: 'google_news',
    engagementScore: 0
  }
}));

// Normalize Reddit items
const posts = $input.first().json.data?.children || [];
return posts.map(p => ({
  json: {
    title: p.data.title,
    link: 'https://www.reddit.com' + p.data.permalink,
    snippet: (p.data.selftext || '').slice(0, 400),
    pubDate: new Date(p.data.created_utc * 1000).toISOString(),
    source: 'reddit',
    engagementScore: (p.data.score || 0) + (p.data.num_comments || 0)
  }
}));

// De-duplicate / cluster near-identical stories by normalized title similarity
const items = $input.all().map(i => i.json);

function normalize(s) {
  return (s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').split(/\s+/).filter(Boolean);
}

function jaccard(a, b) {
  const setA = new Set(a);
  const setB = new Set(b);
  const intersection = [...setA].filter(x => setB.has(x)).length;
  const union = new Set([...setA, ...setB]).size;
  return union === 0 ? 0 : intersection / union;
}

const SIMILARITY_THRESHOLD = 0.6; // tune this - not a verified industry-standard value, just a starting point
const kept = [];

for (const item of items) {
  const tokens = normalize(item.title);
  const isDupe = kept.some(k => jaccard(tokens, normalize(k.title)) >= SIMILARITY_THRESHOLD);
  if (!isDupe) kept.push(item);
}

return kept.map(k => ({ json: k }));

const raw = $input.item.json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { sentiment: 'neutral', intent: 'unrelated', severity: 'low', reason: 'parse_error - verify Groq output format' };
}
return {
  json: {
    title: $('Dedupe Stories').item.json.title,
    link: $('Dedupe Stories').item.json.link,
    snippet: $('Dedupe Stories').item.json.snippet,
    source: $('Dedupe Stories').item.json.source,
    pubDate: $('Dedupe Stories').item.json.pubDate,
    sentiment: parsed.sentiment,
    intent: parsed.intent,
    severity: parsed.severity,
    reason: parsed.reason
  }
};

